ObservationalSUCC.PrincipiaAncestral.sel.type:
ObservationalSUCC.PrincipiaAncestral.selected_endpoint_exact_iff_saturated_reach_closed.{u, v} {X : Type u} {O : Type v}
  (R : X → X → Prop) (q : X → O) (x : X) :
  (∀ (b : O), Reach (QuotientEdge R q) (q x) b ↔ ∃ y, Reach R x y ∧ q y = b) ↔ ForwardClosed R (Saturate q (Reach R x))

ObservationalSUCC.PrincipiaAncestral.end.type:
ObservationalSUCC.PrincipiaAncestral.endpoint_exact_iff_saturation_closed.{u, v} {X : Type u} {O : Type v}
  (R : X → X → Prop) (q : X → O) :
  EndpointExact R q ↔ ∀ (P : X → Prop), ForwardClosed R P → ForwardClosed R (Saturate q P)

ObservationalSUCC.PrincipiaAncestral.clo.type:
ObservationalSUCC.PrincipiaAncestral.closed_invariant_excludes_report.{u, v} {X : Type u} {O : Type v}
  (R : X → X → Prop) (q : X → O) (P : X → Prop) (x : X) (b : O) (closed : ForwardClosed R P) (initial : P x)
  (excludes : ∀ (y : X), P y → q y ≠ b) : ¬∃ y, Reach R x y ∧ q y = b

ObservationalSUCC.PrincipiaAncestral.inv.type:
ObservationalSUCC.PrincipiaAncestral.invariant_refutes_endpoint_exact.{u, v} {X : Type u} {O : Type v}
  (R : X → X → Prop) (q : X → O) (P : X → Prop) (x : X) (b : O) (closed : ForwardClosed R P) (initial : P x)
  (excludes : ∀ (y : X), P y → q y ≠ b) (observed : Reach (QuotientEdge R q) (q x) b) : ¬EndpointExact R q
